<?php
if(!defined('ABSPATH'))exit;
function dgs_news_category($create=false){$cat=get_category_by_slug('school-news');if($cat)return (int)$cat->term_id;if(!$create)return 0;$id=wp_insert_term('اخبار مدرسه','category',array('slug'=>'school-news'));return is_wp_error($id)?$id:(int)$id['term_id'];}
function dgs_news_allowed_post($id){$p=get_post($id);$cat=dgs_news_category();if(!$cat||!$p||$p->post_type!=='post'||$p->post_status==='trash')return false;$cats=array_merge(array($cat),(array)get_term_children($cat,'category'));return (bool)array_intersect($cats,wp_get_post_categories($id));}
function dgs_news_revision($p){return hash('sha256',wp_json_encode(array($p->post_title,$p->post_content,$p->post_status,$p->post_modified_gmt,get_post_thumbnail_id($p->ID))));}
function dgs_news_save($d,$image=0){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','دسترسی مدیریت لازم است.');foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','اطلاعات فرم معتبر نیست.');
 $id=absint($d['news_id']??0);if($id&&!dgs_news_allowed_post($id))return dgs_edu_error('scope','این نوشته از اخبار مدرسه نیست یا حذف شده است.');$title=sanitize_text_field($d['news_title']??'');$body=wp_kses_post($d['news_body']??'');$status=$d['news_status']??'draft';if(!$title||dgs_edu_length($title)>200||trim(wp_strip_all_tags($body))===''||strlen($body)>200000)return dgs_edu_error('fields','عنوان تا۲۰۰ نویسه و متن خبر را وارد کنید.');if(!in_array($status,array('draft','publish'),true))return dgs_edu_error('status','وضعیت انتشار معتبر نیست.');if($image&&!wp_attachment_is_image($image))return dgs_edu_error('image','تصویر معتبر نیست.');
 $lock='dgs_news_save_'.($id?:get_current_user_id().'_new');if(!add_option($lock,time(),'','no'))return dgs_edu_error('busy','خبر در حال ذخیره است؛ کمی بعد دوباره تلاش کنید.');try{
 if($id&&(!dgs_news_allowed_post($id)||!hash_equals(dgs_news_revision(get_post($id)),(string)($d['news_revision']??''))))return dgs_edu_error('stale','خبر تغییر کرده است؛ صفحه ویرایش را دوباره باز کنید.');$cat=dgs_news_category(true);if(is_wp_error($cat))return dgs_edu_error('category','دسته اخبار مدرسه آماده نشد.');
 $row=array('post_type'=>'post','post_title'=>$title,'post_content'=>$body,'post_status'=>$status,'post_category'=>$id?wp_get_post_categories($id):array($cat));if($id)$row['ID']=$id;else $row['post_author']=get_current_user_id();$saved=wp_insert_post(wp_slash($row),true);if(is_wp_error($saved)||!$saved)return dgs_edu_error('save','خبر ذخیره نشد.');if($image)set_post_thumbnail($saved,$image);elseif(($d['remove_image']??'')==='1')delete_post_thumbnail($saved);if(function_exists('dgs_catalog_invalidate'))dgs_catalog_invalidate($saved);dgs_edu_audit($id?'school_news_edit':'school_news_create',$saved);return $saved;
 }finally{delete_option($lock);}
}
function dgs_news_photo(){
 $f=$_FILES['news_photo']??null;if(!$f||($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return 0;$tmp=$f['tmp_name']??'';$info=is_string($tmp)?@getimagesize($tmp):false;if(($f['error']??1)!==UPLOAD_ERR_OK||!is_string($tmp)||!is_uploaded_file($tmp)||($f['size']??0)>3*1024*1024||!$info||$info[0]*$info[1]>20000000||!in_array($info['mime'],array('image/jpeg','image/png','image/webp'),true))return dgs_edu_error('photo','عکس سالم JPG/PNG/WebP تا۳مگابایت انتخاب کنید.');require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/image.php';return media_handle_upload('news_photo',0,array(),array('test_form'=>false,'mimes'=>array('jpg|jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp')));
}
add_action('admin_post_dgs_panel_news',function(){
 if(!current_user_can('dgs_manage_education')||($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('دسترسی ندارید.','',array('response'=>403));check_admin_referer('dgs_panel_news','news_nonce');$d=wp_unslash($_POST);$id=is_scalar($d['news_id']??null)?absint($d['news_id']):0;if($id&&!dgs_news_allowed_post($id))wp_die('خبر مجاز نیست.','',array('response'=>403));$image=dgs_news_photo();$r=is_wp_error($image)?$image:dgs_news_save($d,$image);if(is_wp_error($r)&&is_int($image)&&$image)wp_delete_attachment($image,true);$token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,array('error'=>is_wp_error($r),'text'=>is_wp_error($r)?$r->get_error_message():'خبر '.(($d['news_status']??'')==='publish'?'منتشر':'به‌صورت پیش‌نویس ذخیره').' شد.'),300);
 $args=array('dg_notice'=>$token);if(is_wp_error($r)){set_transient('dgs_news_form_'.get_current_user_id().'_'.$token,$d,300);$args['news_edit']=$id?:'new';}$year=is_string($d['year']??null)?dgs_edu_year($d['year']):'';wp_safe_redirect(add_query_arg($args,dgs_edu_url('news',$year?:dgs_edu_current_year())),303);exit;
});
function dgs_edu_view_news($year){
 if(!current_user_can('dgs_manage_education'))return '';$base=dgs_edu_url('news',$year);$edit=dgs_att_get('news_edit');$h='<div class="dsp-school dgs-panel-news">'.dgs_school_title('اخبار مدرسه','ثبت و انتشار خبر در صفحه اصلی و بخش اخبار مدرسه');
 if($edit!==''){$id=$edit==='new'?0:absint($edit);if($edit!=='new'&&(!$id||!dgs_news_allowed_post($id)))return $h.dgs_empty('خبر مجاز پیدا نشد.').'</div>';$p=$id?get_post($id):null;$d=array('news_title'=>$p?$p->post_title:'','news_body'=>$p?$p->post_content:'','news_status'=>$p&&$p->post_status==='publish'?'publish':'draft','news_revision'=>$p?dgs_news_revision($p):'');$token=dgs_att_get('dg_notice');$key='dgs_news_form_'.get_current_user_id().'_'.$token;$old=$token?get_transient($key):false;if(is_array($old)){foreach(array_keys($d) as $k)if(is_string($old[$k]??null))$d[$k]=$old[$k];delete_transient($key);}
 $h.='<section class="dsp-card"><a class="dg-btn dg-btn-outline" href="'.esc_url($base).'">بازگشت به فهرست خبرها</a><h3>'.($id?'ویرایش خبر':'خبر جدید').'</h3><form class="dge-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_panel_news','news_nonce',true,false).'<input type="hidden" name="action" value="dgs_panel_news"><input type="hidden" name="year" value="'.esc_attr($year).'"><input type="hidden" name="news_id" value="'.$id.'"><input type="hidden" name="news_revision" value="'.esc_attr($d['news_revision']).'"><label>عنوان خبر<input name="news_title" maxlength="200" value="'.esc_attr($d['news_title']).'" required></label><label>متن خبر<textarea name="news_body" rows="12" required>'.esc_textarea($d['news_body']).'</textarea></label><label>تصویر خبر (اختیاری، تا۳مگابایت)<input name="news_photo" type="file" accept="image/jpeg,image/png,image/webp"></label>';
 if($id&&has_post_thumbnail($id))$h.=get_the_post_thumbnail($id,'thumbnail').'<label><input type="checkbox" name="remove_image" value="1">برداشتن تصویر فعلی</label>';
 return $h.dgs_edu_select('news_status','وضعیت',array('draft'=>'پیش‌نویس؛ فقط مدیریت می‌بیند','publish'=>'انتشار در سایت'),$d['news_status']).'<button class="dg-btn">ذخیره خبر</button></form></section></div>';}
 $h.='<section class="dsp-card"><div class="dsp-section-head"><h3>فهرست اخبار مدرسه</h3><a class="dg-btn" href="'.esc_url(add_query_arg('news_edit','new',$base)).'">افزودن خبر</a></div>'; $page=max(1,absint(dgs_att_get('news_page','1')));$cat=dgs_news_category();$q=new WP_Query(array('post_type'=>'post','post_status'=>array('publish','draft','pending'),'cat'=>$cat?:0,'post__in'=>$cat?array():array(0),'posts_per_page'=>15,'paged'=>$page,'orderby'=>'date','order'=>'DESC'));$h.=dgs_edu_table_start(array('عنوان','وضعیت','عملیات'));foreach($q->posts as $p){$h.='<tr><td>'.esc_html($p->post_title).'</td><td>'.esc_html(array('publish'=>'منتشرشده','draft'=>'پیش‌نویس','pending'=>'در انتظار تأیید')[$p->post_status]).'</td><td><a class="dge-small-btn" href="'.esc_url(add_query_arg('news_edit',$p->ID,$base)).'">ویرایش</a>';if($p->post_status==='publish')$h.=' <a class="dge-small-btn" href="'.esc_url(get_permalink($p)).'">مشاهده خبر</a>';$h.='</td></tr>';}if(!$q->posts)$h.='<tr><td colspan="3">هنوز خبری ثبت نشده است.</td></tr>';$h.='</tbody></table></div>';if($page>1)$h.='<a class="dg-btn dg-btn-outline" href="'.esc_url(add_query_arg('news_page',$page-1,$base)).'">قبلی</a>';if($page<$q->max_num_pages)$h.='<a class="dg-btn dg-btn-outline" href="'.esc_url(add_query_arg('news_page',$page+1,$base)).'">بعدی</a>';return $h.'</section></div>';
}
